import React, { useEffect, useState } from "react";
import api from "../services/api";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";

const AdminDashboard = () => {
  const [metrics, setMetrics] = useState([]);
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    api.get("/api/agent/metrics")
      .then((response) => {
        setMetrics(response.data);
      })
      .catch((error) => {
        console.error("Error fetching metrics:", error);
      });
  }, []);

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleAutomateResolution = () => {
    alert("Automated resolution triggered!");
    // Add API call or logic for triggering automation
  };

  return (
    <div
      className="p-6 min-h-screen"
      style={{
        backgroundColor: darkMode ? "#1e293b" : "#f8fafc",
        color: darkMode ? "#f8fafc" : "#1e293b",
      }}
    >
      {/* Navbar */}
      <div className="flex flex-col items-center mb-6">
        <h1 className="text-2xl font-bold">Admin Dashboard</h1>
        <button
          onClick={handleToggleDarkMode}
          className="mt-2 px-4 py-2 bg-blue-500 text-white rounded"
        >
          Toggle {darkMode ? "Light" : "Dark"} Mode
        </button>
      </div>

      {/* Widgets Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* Monitoring Widget */}
        <MonitoringWidget />

        {/* Machine Learning Widget */}
        <MLWidget />

        {/* Server Metrics */}
        {metrics.map((metric, index) => (
          <div
            key={index}
            className="bg-white shadow-md p-4 rounded-lg"
            style={{
              backgroundColor: darkMode ? "#2d3748" : "#fff",
              color: darkMode ? "#f8fafc" : "#1e293b",
            }}
          >
            <h3 className="text-lg font-semibold">Server: {metric.server_id}</h3>
            <p>CPU Usage: {metric.cpu_usage}%</p>
            <p>Memory Usage: {metric.memory_usage}%</p>
            <p>Disk Usage: {metric.disk_usage}%</p>
            <p>Uptime: {Math.round(metric.uptime / 3600)} hours</p>
            <p>
              Logs: {metric.logs ? JSON.parse(metric.logs).slice(0, 5).join(", ") : "No logs available"}
            </p>
          </div>
        ))}

        {/* Automated Resolution Widget */}
        <div
          className="p-4 rounded-lg shadow-md text-center"
          style={{
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            color: darkMode ? "#f8fafc" : "#1e293b",
          }}
        >
          <h3 className="text-lg font-semibold">Automated Resolution</h3>
          <button
            onClick={handleAutomateResolution}
            className="mt-2 px-4 py-2 bg-green-500 text-white rounded"
          >
            Trigger Automation
          </button>
          <p className="mt-2 text-sm">
            This will automatically resolve common server issues, including:
          </p>
          <ul className="list-disc text-left pl-4 mt-2 text-sm">
            <li>Clearing cache</li>
            <li>Restarting affected services</li>
            <li>Freeing up memory</li>
            <li>Updating configuration files</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
